DELETE FROM yz_card_route

    cd_id IN

        #{cd_id_arrs}


        AND cd_agent_id = #{cd_agent_id}

mapper.update:
UPDATE yz_card_route
cd_status = 3, cd_delete = now()
cd_id = #{cd_id}

mapper.select:
SELECT a.cd_id, a.cd_name, b.dict_label, cd_alias FROM yz_card_route a, sys_dict_data b
a.cd_operator_type = b.dict_value AND b.dict_type = 'yunze_card_operators_type'
AND a.cd_operator_type = #{cd_operator_type}
AND a.cd_id = #{channel_id}

SELECT a.vid, a.msisdn, a.iccid, a.imsi, a.imei, a.used, a.remaining, a.status_ShowId AS statusId, a.package_id AS packageId, a.type, a.remarks AS 'remark', a.customize_grouping AS 'grouping', a.deliver_date AS 'deliverDate', a.activate_date AS 'activateDate', DATE_FORMAT( a.due_expire_time, "%Y-%m-%d %H:%i:%S" ) AS 'expireTime', ( SELECT dept_name FROM sys_dept WHERE dept_id = a.dept_id ) AS deptName, ( SELECT package_agentname FROM yz_card_package WHERE package_id = a.package_id ) AS packageName FROM yz_card_info a WHERE a.dept_id in
#{deptIdArr}
AND a.imsi = #{cardno} OR a.iccid = #{cardno}
OR a.msisdn = #{cardno}

SELECT
a.iccid
FROM
yz_card_info a
WHERE
a.dept_id in

    #{deptIdArr}


    and a.vid = #{cardno}


    and a.msisdn = #{cardno}


    and a.iccid = #{cardno}


    and a.imsi = #{cardno}

SELECT cd_id, cd_code, cd_name, cd_username, cd_pwd, cd_key, cd_status, cd_concurrency, cd_control_type, cd_algorithm, sms_host, sms_port, sms_source_addr, sms_shared_secret, sms_code, sms_src_TerminalId, sync_change_notification, sync_data_type, upstream_card_count, sync_field FROM yz_card_route
cd_status = '1'
and cd_lunxun = #{cd_lunxun}
and cd_lunxun = '1'
and cd_id =#{FindCd_id}
and sync_upstream =#{sync_upstream}
and cd_algorithm =#{cd_algorithm}
and LENGTH(trim(sms_code )) > 1
and cd_id IN
#{Cd_idArr}
and cd_code IN
#{cd_codeArr}
group by sms_src_TerminalId

SELECT
used
FROM
yz_card_info

    iccid = #{iccid}
    OR vid = #{iccid}
    OR msisdn = #{iccid}
    OR imsi = #{iccid}

SELECT
COUNT(1)
FROM
yz_card_info a


        and a.vid = #{cardno}


        and a.msisdn = #{cardno}


        and a.iccid = #{cardno}


        and a.imsi = #{cardno}

SELECT cd_id, cd_operator_type FROM yz_card_route
cd_operator_type IN
#{cd_operator_type}

SELECT a.vid, a.msisdn, a.iccid, a.imsi, a.imei, a.used, a.remaining, a.channel_id, a.status_ShowId AS statusId, a.package_id AS packageId, a.type, a.remarks AS 'remark', a.customize_grouping AS 'grouping', a.deliver_date AS 'deliverDate', a.activate_date AS 'activateDate', DATE_FORMAT( a.due_expire_time, "%Y-%m-%d %H:%i:%S" ) AS 'expireTime', (SELECT dept_name FROM sys_dept WHERE dept_id = a.dept_id ) as deptName, (SELECT package_agentname FROM yz_card_package WHERE package_id = a.package_id ) as packageName FROM yz_card_info a WHERE a.dept_id = a.agent_id
and a.vid = #{cardno}
and a.msisdn = #{cardno}
and a.iccid = #{cardno}
and a.imsi = #{cardno}

