UPDATE yz_card_route
cd_key = #{cd_key}, updateTime = now()
cd_id = #{cd_id}

UPDATE yz_card_info
imei = #{imei}, syn_Time = now()
iccid = #{iccid}

mapper.select:
SELECT t1.iccid, t1.imsi, t1.msisdn, DATE_FORMAT( t1.open_date, "%Y-%m-%d" ) AS openDate, t2.cd_useraccount, t2.cd_key, t2.cd_pwd, t2.cd_username, t1.used, t1.remaining, DATE_FORMAT( t1.activate_date, "%Y-%m-%d" ) AS activateDate, DATE_FORMAT( t1.due_expire_time, "%Y-%m-%d" ) AS expireTime, t1.status_ShowId AS statusId, t1.remarks, t2.cd_code, t2.cd_name, t3.dept_name AS deptName, t5.packet_wx_name AS packetName, t6.package_name AS packageName, t5.packet_valid_time AS validTime, t5.packet_valid_name AS validName, t5.error_flow AS errorFlow FROM yz_card_info t1 LEFT JOIN yz_card_route t2 ON t1.channel_id = t2.cd_id LEFT JOIN sys_dept t3 ON t1.agent_id = t3.dept_id LEFT JOIN yz_card_flow t4 ON t1.iccid = t4.iccid LEFT JOIN yz_card_packet t5 ON t4.packet_id = t5.packet_id LEFT JOIN yz_card_package t6 ON t1.package_id=t6.package_id WHERE t1.iccid = #{value}
OR t1.imsi = #{value}
OR t1.msisdn = #{value}
ORDER BY t4.end_time DESC LIMIT 1

mapper.update:
update yz_card_info
set used=#{used},
    remaining=#{remaining}
where iccid = #{iccid}
